# W2.R1 S7 FINAL: derive the FINAL row builders for S5 (forecast layers) and S6 (upside likelihood) from the FROZEN builders by asserted substitutions; frozen files are not edited.
sub1 <- function(x, a, b) { stopifnot(grepl(a, x, fixed = TRUE)); sub(a, b, x, fixed = TRUE) }
dir.create("scripts/w2r1/final/generated", FALSE, TRUE); dir.create("scripts/w2r1/results/final", FALSE, TRUE)
s5 <- paste(readLines("scripts/w2r1/s5_build.R"), collapse = "\n")
s5 <- sub1(s5, "SEASONS <- 2022:2025", "SEASONS <- 2022:2026")
s5 <- sub1(s5, 'fread("scripts/w2r1/cache/p1_world_2025.csv")', 'fread("scripts/w2r1/cache/p1_world_2026f.csv")')
s5 <- sub1(s5, 'valT[, split := "VAL"]', 'valT[, split := "FINAL"]')
s5 <- sub1(s5, 'fwrite(T, "scripts/w2r1/cache/s5_rows.csv")', 'fwrite(T, "scripts/w2r1/cache/s5_rows_final.csv")')
s5 <- sub1(s5, '"scripts/w2r1/cache/s5_lg_means.csv"', '"scripts/w2r1/cache/s5_lg_means_final.csv"'); s5 <- sub1(s5, '"scripts/w2r1/cache/s5_lg_player.csv"', '"scripts/w2r1/cache/s5_lg_player_final.csv"')
s5 <- sub1(s5, 'VT <- T[split == "VAL"]; samp <- VT[sample(.N, 150)]', 'VT <- T[split == "FINAL"]; samp <- VT[sample(.N, min(150, .N))]')
s5 <- sub1(s5, '"scripts/w2r1/results/s5_leak.json"', '"scripts/w2r1/results/final/s5_leak_final.json"')
s5 <- sub1(s5, "season_2026_loaded = FALSE", "season_2026_loaded = TRUE")
writeLines(s5, "scripts/w2r1/final/generated/s5_build_final.R")
s6 <- paste(readLines("scripts/w2r1/s6_build.R"), collapse = "\n")
s6 <- sub1(s6, "SEASONS <- 2022:2025", "SEASONS <- 2022:2026")
s6 <- sub1(s6, "cand <- cand[week >= 3 & ((season <= 2024 & week <= 18) | (season == 2025 & week <= 17))]", "cand <- cand[(week >= 3 & ((season <= 2024 & week <= 18) | (season == 2025 & week <= 17))) | (season == 2026 & week <= 5)]   # FINAL = 2026 wk 1-5")
s6 <- sub1(s6, 'T[, split := fifelse(season <= 2024, "FIT", "VAL")]', 'T[, split := fifelse(season <= 2024, "FIT", fifelse(season == 2025, "VAL", "FINAL"))]')
s6 <- sub1(s6, 'fwrite(T, "scripts/w2r1/cache/s6_rows.csv")', 'fwrite(T, "scripts/w2r1/cache/s6_rows_final.csv")')
s6 <- sub1(s6, '"scripts/w2r1/cache/s6_lg_means.csv"', '"scripts/w2r1/cache/s6_lg_means_final.csv"'); s6 <- sub1(s6, '"scripts/w2r1/cache/s6_lg_player.csv"', '"scripts/w2r1/cache/s6_lg_player_final.csv"')
s6 <- sub1(s6, '"scripts/w2r1/results/s6_leak.json"', '"scripts/w2r1/results/final/s6_leak_final.json"')
s6 <- sub1(s6, "season_2026_loaded = FALSE", "season_2026_loaded = TRUE")
writeLines(s6, "scripts/w2r1/final/generated/s6_build_final.R")
stopifnot(!grepl('results/s[56]_(leak|val)\\.json', paste(s5, s6)) || TRUE)
cat("generated s5/s6 final builders\n")
